(* UCodeShP.v -- the CODE CATALOG of the user program [shp].
   AUTO-GENERATED by tools/gen_ucode.py.  DO NOT EDIT BY HAND.

   The verified-user tier (claude-notes/projects/user-verified.md) drives
   one step from one [uinstr] fact (UmodeMem.v): the pure statement that at
   a given user pc the program's bytes sit in the process image [M], the
   pc's page is mapped fetch-executable, and the fetched word decodes to a
   named AST on any U-mode machine. This file proves those facts for the
   564 instruction(s) of this catalog, from the dumped image
   [User.ShInstrs.sh_bytes].

   Two premises carry every [uinstr] lemma:

     [shp_text_sub M]   -- [M] contains the dumped text (so a proof may talk
                          about a process image that ALSO has rodata, bss, a
                          stack page and an argument area in it);
     [shp_text_layout pt]
                       -- the pure page-table fact: each of the 2 page(s) of
                          the executable segment (0x0 .. 0x1fff) is mapped with a
                          leaf that permits instruction FETCH and a user data
                          LOAD.  The load half is not decoration: a program's
                          .rodata shares a text page and its string literals are
                          handed to [write]/[exec] as buffers.  The DATA page and
                          the heap are NOT this file's business -- they are
                          read-WRITE and belong to USpecShp.v, as do the stack and
                          argv facts.

   Image geometry, as dumped:
     text  0x0 .. 0x1280   (4736 bytes)
     PT_LOAD 0x0      filesz 0x1c54   memsz 0x1c54   flags 5   (executable: 2 text page(s))
     PT_LOAD 0x2000   filesz 0x10     memsz 0x98     flags 6
     data  0x1280 .. 0x2010   (2532 bytes)
     entry 0x9d0, MemBase 0x0, MemEnd 0x2098

   Catalogued: 564 instruction(s), 359 distinct word(s), in 11 function(s):
     <parsecmd>       0x86e    .. 0x8de       42 instr
     <parseline>      0x6e2    .. 0x768       56 instr
     <parsepipe>      0x682    .. 0x6e0       41 instr
     <parseexec>      0x590    .. 0x680       92 instr
     <parseredirs>    0x4ac    .. 0x58e       85 instr
     <nulterminate>   0x7ee    .. 0x86c       50 instr
     <peek>           0x448    .. 0x4aa       40 instr
     <gettoken>       0x310    .. 0x446      104 instr
     <execcmd>        0x1d2    .. 0x1fe       19 instr
     <strlen>         0xa30    .. 0xa5a       18 instr
     <strchr>         0xa82    .. 0xaa8       17 instr

   NOT catalogued, because no proof ever fetches it:
       memset -- already catalogued in iris/UCodeShK.v; the walk reuses
       [UkSh.wp_ksh_memset] across the [shp_code]/[shk_code] bridge
       atoi, chdir, close, dup, exec, exit, fork, fork1, fprintf, free, fstat,
       getcmd, getpid, gets, kill, link, main, memcmp, memcpy, memmove, mkdir,
       mknod, open, pause, pipe, printf, printint, putc, read, runcmd, sbrk,
       sbrklazy, start, stat, strcmp, strcpy, sync, sys_sbrk, unlink, uptime,
       vprintf, wait, write -- not on the parser's path: the command loop and
       the ELF entry are UCodeShK.v's (SH lane stages 1-2), the allocator is
       stage 3's, and runcmd's tree walk with its fork/exec arms is stage 5's
       backcmd -- reached only from parseline's [peek(ps,es,'&')] loop --
       excluded by [ushp_no_symbols]
       listcmd -- reached only from parseline's [peek(ps,es,';')] arm --
       excluded by [ushp_no_symbols]
       pipecmd -- reached only from parsepipe's [peek(ps,es,'|')] arm --
       excluded by [ushp_no_symbols]
       redircmd -- reached only from parseredirs' switch, which runs only when
       [peek(ps,es,'<>')] is true -- excluded by [ushp_no_symbols]
       parseblock -- reached only through [peek(ps,es,'(')] in parseexec, and a
       '(' is a symbol byte -- excluded by the walk's [ushp_no_symbols] premise
       on the line, so no instruction of it is ever fetched
       malloc -- stage 3's; stage 4 states its contract as the named local
       Hypothesis [ushp_malloc_ok], which crosses the call without fetching a
       single instruction of the allocator
       panic -- the two [panic] calls this walk crosses -- parseexec's 'syntax'
       and 'too many args' -- are REFUTED, not proved: on a symbol-free line
       every token [gettoken] returns is 'a' or 0, and the argument count is
       bounded by the token list's length

   SH LANE STAGE 4: the recursive-descent PARSER and the lexer under it.
   [parsecmd] takes the line [main]'s blank scan left, measures it with
   [strlen], and calls [parseline] -> [parsepipe] -> [parseexec], each of
   which guards its own constructor with a [peek] for a symbol byte; the
   argument loop in [parseexec] calls [gettoken] once per token and records
   the token's two boundaries in the execcmd node [execcmd] allocated.
   [nulterminate] then writes a NUL at every recorded end, turning the
   token BOUNDARIES into the argv vector [exec] observes. [peek] and
   [gettoken] both run over the two static tables at 0x2000 (symbols) and
   0x2008 (whitespace) with [strchr]. WHAT IS NOT HERE, AND WHY IT IS NOT A
   GAP. [malloc] is stage 3's, and stage 4 states its contract as the one
   named local Hypothesis [ushp_malloc_ok] in iris/UkShParse.v -- the
   Hypothesis consumes the run at malloc's ENTRY pc and hands it back at
   the return address, so no instruction of malloc is ever fetched by this
   walk and a catalog fact about one would be a claim nothing reads.
   [memset], which [execcmd] calls, is already catalogued in UCodeShK.v and
   the walk reuses [UkSh.wp_ksh_memset] across the [shp_code]/[shk_code]
   bridge.

   Every AST below was READ OFF the model -- [vm_compute] of the decoder at
   the U-mode reference state [dstateU] (base) / [decode_c_pure] under the
   misa.C gate (compressed) -- never guessed. In particular every
   jal/branch immediate is the decoder's POSITIVE residue, and a COMPRESSED
   branch or jump immediate counts HALFwords. The compressed words decode
   to the raw C_* constructors -- the expansion into ITYPE/STORE/...
   happens in [execute], not here.
 *)
